select
  count(*) filter (where p.code_cj is not null) as "มีอยู่แล้ว (จะอัปเดต)",
  count(*) filter (where p.code_cj is null)     as "ยังไม่มี (จะเพิ่มใหม่)",
  count(*)                                      as "รวมในไฟล์"
from ไฟล์ใหม่ f
left join parts p on p.code_cj = f.code_cj;


-- ---------------------------------------------------------------- บล็อก B
-- อ่านอย่างเดียว: 2 เรื่องที่ควรดูก่อนรันจริง
-- B1) รหัสอะไหล่ที่ซ้ำกันเองในฐานข้อมูล (ถ้ามี การอัปเดตจะโดนทุกแถวที่ซ้ำ)
select code_cj as "รหัสที่ซ้ำในฐานข้อมูล", count(*) as "จำนวนแถว"
from parts group by code_cj having count(*) > 1 order by count(*) desc;

