select p.code_cj as "รหัสที่ไม่มีในไฟล์", p.name as "ชื่อ", p.unit_price as "ราคา CJ"
from parts p
where not exists (select 1 from ไฟล์ใหม่ f where f.code_cj = p.code_cj)
order by p.code_cj;


