-- อัปเดตรายการที่มีรหัสอยู่แล้ว (แก้ทุกช่องตามไฟล์ ยกเว้น id / image_url ที่ไม่ได้อยู่ในไฟล์)
update parts p
set name             = f.name,
    brand            = f.brand,
    model            = f.model,
    detail           = f.detail,
    unit             = f.unit,
    warranty_months  = f.warranty_months,
    unit_price       = f.unit_price,
    return_old_part  = f.return_old_part,
    company          = f.company,
    "Unit Custumer"  = f.unit_custumer,
    updated_at       = now()
