select f.code_cj as "รหัสที่ยังไม่ตรง",
       p.unit_price as "ราคา CJ ในฐานข้อมูล", f.unit_price as "ราคา CJ ในไฟล์",
       p."Unit Custumer" as "ราคาผู้รับเหมา ในฐานข้อมูล", f.unit_custumer as "ราคาผู้รับเหมา ในไฟล์"
from ไฟล์ใหม่ f
left join parts p on p.code_cj = f.code_cj
where p.code_cj is null
   or p.unit_price is distinct from f.unit_price
   or p."Unit Custumer" is distinct from f.unit_custumer
   or p.unit is distinct from f.unit;
